import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';import {serveStatic} from '../../engine/static.mjs';
const artifact=path.resolve(process.argv[2]||'artifacts/platform/events'),root=path.join(artifact,'project/output'),index=JSON.parse(await readFile(path.join(root,'assets/search-index.json'))),events=index.filter(x=>x.kind==='event');assert.ok(events.length>=2);const target=events.find(e=>e.route.includes('evening-concert'))||events[0],term=target.title.split(/\s+/)[0],expected=events.filter(e=>(e.title+' '+e.text).toLocaleLowerCase().includes(term.toLocaleLowerCase()));let browser,server;const cases=[];
try{server=await serveStatic(root);browser=await chromium.launch({channel:'chrome'});for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:844}});await page.goto(server.url+'/events/',{waitUntil:'networkidle'});const form=page.locator('form.tribe-events-c-search');if(!await form.locator('input[type=text]').isVisible())await page.locator('.tribe-events-c-events-bar__search-button').click();await form.locator('input[type=text]').fill(term);await form.locator('button[type=submit]').click();await page.locator('.migration-search-dialog[open] li a').first().waitFor();const routes=await page.locator('.migration-search-dialog li a').evaluateAll(es=>es.map(e=>new URL(e.href).pathname));assert.deepEqual(routes.sort(),expected.map(e=>e.route).sort());assert.ok(routes.includes(target.route));await page.keyboard.press('Escape');assert.equal(await page.locator('.migration-search-dialog').evaluate(e=>e.open),false);const subscribe=page.locator('.tribe-events-c-subscribe-dropdown__button-text');await subscribe.click();assert.equal(await subscribe.getAttribute('aria-expanded'),'true');const calendarLink=page.locator('.tribe-events-c-subscribe-dropdown__list-item--ics a');assert.ok(await calendarLink.isVisible());const calendarURL=new URL(await calendarLink.getAttribute('href'),server.url);assert.equal(calendarURL.origin,new URL(server.url).origin);const calendarResponse=await page.request.get(calendarURL.href);assert.equal(calendarResponse.status(),200);assert.match(await calendarResponse.text(),/BEGIN:VCALENDAR/);await page.keyboard.press('Escape');assert.equal(await subscribe.getAttribute('aria-expanded'),'false');cases.push({width,eventResults:routes,escapeCloses:true,subscriptionDisclosure:true,localCalendarHTTP:calendarResponse.status()});await page.close();}await writeFile(path.join(artifact,'event-search-check.json'),JSON.stringify({generatedExport:true,cases,sourceRequests:0,aiCalls:0},null,2));console.log(JSON.stringify({cases:cases.length}));}finally{await browser?.close();await server?.close();}
